// Made by tools/build-functions.js from index.html and word-filter.js. Don't edit by hand.
'use strict';
const window = {};
// Shared word filter for the arcade and ITAP Adventure: player names and chat.
// The list combines a hand-made list with LDNOOBW (CC BY 4.0) and zacanger/profane-words (MIT), stored encoded.
(function () {
  const SUB = atob('').split(',');    // blocked anywhere inside a word
  const WORD = new Set(atob('').split(','));   // blocked only as a whole word (so CLASS, GRAPE, HELLO stay OK)
  // read a word the way a person would: letters only, with number and symbol look-alikes turned into letters
  const LEET = { '0': 'O', '1': 'I', '3': 'E', '4': 'A', '5': 'S', '7': 'T', '8': 'B', '@': 'A', '$': 'S', '!': 'I', '|': 'I', '+': 'T' };
  const norm = w => w.toUpperCase().split('').map(c => LEET[c] || c).join('').replace(/[^A-Z]/g, '');
  const squash = w => w.replace(/(.)\1+/g, '$1');   // "fuuuuck" -> "fuck"
  const bad = w => { const n = norm(w); if (!n) return false;
    for (const v of [n, squash(n)]) { if (WORD.has(v) || SUB.some(b => v.includes(b))) return true; }
    return false; };
  // words the name list blocks that are fine in chat, where people talk about fighting, dying and being silly
  const CHAT_OK = new Set('DIE,DEATH,KILL,KILLER,MURDER,BLOOD,GORE,STUPID,IDIOT,IDIOTS,DUMB,MORON,NOOB,LOSER,LOSERS,UGLY,TRASH,GARBAGE,JUNK,POOP,PEE,FART,FARTS,FARTING,BUTT,BUTTS,SNOT,PUKE,VOMIT,TURD,WHACK,BOOTY,TORTUR,WEED,SLAVE'.split(','));
  // mask every rude word in a chat line; letters spaced out ("f u c k") are caught too
  const badChat = w => !CHAT_OK.has(squash(norm(w))) && !CHAT_OK.has(norm(w)) && bad(w);
  window.cleanText = text => {
    const parts = String(text).split(/(\s+)/);
    const words = parts.map((p, i) => ({ p, i })).filter(x => !/^\s*$/.test(x.p));
    const out = parts.slice();
    words.forEach(({ p, i }) => { if (badChat(p)) out[i] = '*'.repeat(Math.min(8, p.length)); });
    // runs of single characters, joined, so spacing cannot sneak a word through
    for (let a = 0; a < words.length; a++) {
      if (norm(words[a].p).length !== 1) continue;
      let b = a; while (b + 1 < words.length && norm(words[b + 1].p).length === 1) b++;
      if (b - a >= 2 && bad(words.slice(a, b + 1).map(x => x.p).join(''))) for (let k = a; k <= b; k++) out[words[k].i] = '*';
      a = b;
    }
    return out.join('');
  };
  window.isBadName = name => bad(name) || String(name).split(/[\s_.-]+/).some(bad);
})();

const BAD_SUB = atob('').split(',');    // blocked anywhere inside a name
const BAD_WORD = new Set(atob('').split(','));   // blocked only as a whole word (so CLASS, GRAPE, HELLO, TITAN stay OK)
const LEET = {'@':'A','$':'S','!':'I','|':'I','0':'O','3':'E','4':'A','5':'S','7':'T','8':'B'};
function _badName(name) {
  const raw = String(name).toUpperCase();
  const leet = one => raw.replace(/[@$!|0134578]/g, c => c === '1' ? one : LEET[c]);   // catches $H1T, F4G, etc.
  for (const v of [leet('I'), leet('L'), raw]) {
    const compact = v.replace(/[^A-Z0-9]/g, '');                                 // catches F U C K, F.U.C.K
    if (BAD_SUB.some(w => compact.includes(w)) || BAD_WORD.has(compact)) return true;
    if (v.split(/[^A-Z0-9]+/).some(tok => tok && BAD_WORD.has(tok))) return true;
  }
  return false;
}
const nameKey = n => (n.toLowerCase().replace(/[^a-z0-9]/g, '') || 'anon');
const badName = name => _badName(name) || window.isBadName(name);
module.exports = { badName, nameKey };
